def clean(df):
    df = df.copy()
    df['species'] = df['species'].replace({
        'adelie': 'Adelie',
        'gentoo': 'Gentoo',
        'chinstrap': 'Chinstrap',
        'Gentto': 'Gentoo'
    })
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    return df

def answer(df):
    result = df.groupby('species')['flipper_length_mm'].mean().to_dict()
    return result
